function dec2hex(dec){if(dec<=0){return"0"}let hex="";let digit;while(dec>0){digit=dec%16;hex=String.fromCharCode(digit+(digit<10?48:87))+hex;dec=Math.floor(dec/16)}return hex}function unpackID(packedID){let retval="";for(i=0;i<packedID.length;i++){retval+=dec2hex(packedID.charCodeAt(i))}return retval}function hex2dec(hex){hex=hex.toUpperCase();let dec=0;let c;for(let i=0;i<hex.length;++i){dec*=16;c=hex.charAt(i);if(c>="0"&&c<="9"){dec+=hex.charCodeAt(i)-48}else if(c>="A"&&c<="F"){dec+=hex.charCodeAt(i)-55}else{return 0}}return dec}function packID(unpackedID){var packedID="";let code;for(let j=0;j<unpackedID.length;j+=2){code=hex2dec(unpackedID.substring(j,j+2));if(code!==0){packedID+=String.fromCharCode(code)}else{return""}}return packedID}function prooveFilled(formName,fields){const myform=document.forms[formName];let val;for(let i=0;i<fields.length;++i){val=getControlValue(formName,fields[i]);if(val==""){myform[fields[i]].focus();alert("You didn't fill in some required field.");return false}}return true}function prooveFilledIf(formName,fields){const myform=document.forms[formName];let parVal,val,proove;for(let i=0;i<fields.length;++i){parVal=getControlValue(formName,fields[i][1]);val=fields[i][2];proove=val==""&&parVal!=""||parVal==val;if(!proove){myform[fields[i][0]].focus;alert("You didn't fill in some required field.");return false}}}function getYearNetscapeSafe(myDate){let year=myDate.getYear();return year<200?year+1900:year}function saveDate(formName,dateField,targetField,emptyValue){let myDate=getAADate(formName,dateField,emptyValue);const myField=document.forms[formName][targetField];if(myDate!==0){const d=new Date;d.setTime(myDate);myField.value=d.getMonth()+1+"/"+d.getDate()+"/"+getYearNetscapeSafe(d)}else{myField.value=""}}function setDay(formName,dateField,startYear,myDate){let tryDate=new Date(2e3,1,1);let dayShift=1-tryDate.getDate();document.forms[formName][dateField+"_day"].selectedIndex=myDate.getDate()-dayShift-1;document.forms[formName][dateField+"_month"].selectedIndex=myDate.getMonth();document.forms[formName][dateField+"_year"].selectedIndex=getYearNetscapeSafe(myDate)-startYear}function setToday(formName,dateField,startYear){setDay(formName,dateField,startYear,new Date)}function getAADate(formName,dateField,emptyValue){const f=document.forms[formName];let month=f[dateField+"_month"].value;let day=f[dateField+"_day"].value;let year=f[dateField+"_year"].value;return month!=emptyValue&&day!=emptyValue&&year!=emptyValue?new Date(year,month-1,day).getTime():0}function setControlOrAADate(formName,controlName,newValue,datePrefix,html,timeZone){let myName;if(getControlByName(formName,controlName)!=null){setControl(formName,controlName,newValue);if(html){setControl(formName,controlName+"html",html)}}else if(getControlByName(formName,controlName+"[]")!=null){setControl(formName,controlName+"[]",newValue)}else if(!isNaN(newValue)){myName=datePrefix+controlName;if(getControlByName(formName,myName+"_day")!=null){var myDate=new Date;var timeStamp=Number(newValue);timeStamp+=(myDate.getTimezoneOffset()/60-timeZone)*3600;myDate.setTime(timeStamp*1e3);setControl(formName,myName+"_day",myDate.getDate());setControl(formName,myName+"_month",myDate.getMonth()+1);setControl(formName,myName+"_year",getYearNetscapeSafe(myDate))}}}function getControlByName(formName,controlName){return document.forms[formName]==null?null:document.forms[formName][controlName]}function setControl(formName,controlName,newValue){setThisControl(getControlByName(formName,controlName),newValue)}function setThisControl(myControl,newValue){if(myControl!=null){if(typeof myControl.type=="undefined"){for(var iCtrl=0;iCtrl<myControl.length;++iCtrl){if(myControl[iCtrl].value==newValue){if(myControl[iCtrl].type=="checkbox"||myControl[iCtrl].type=="radio"){myControl[iCtrl].checked=1}break}}}else if(myControl.type.substring(0,6)==="select")for(var i=0;i<myControl.options.length;i++){if(myControl.options[i].value==newValue||myControl.options[i].value==""&&myControl.options[i].text==newValue){myControl.options[i].selected=true}}else if(myControl.type=="checkbox"){myControl.checked=newValue!=0}else{myControl.value=newValue}}}function setControlArray(formName,controlName,newArray){let i,j;const myControl=getControlByName(formName,controlName);if(myControl!=null){if(myControl.type=="select-multiple"){for(j=0;j<newArray.length;j++){for(i=0;i<myControl.options.length;i++){if(myControl.options[i].value==newArray[j]||myControl.options[i].value==""&&myControl.options[i].text==newArray[j]){myControl.options[i].selected=true;break}}if(i===myControl.options.length){myControl.options[i]=new Option(newArray[j],newArray[j],false,false);myControl.options[i].selected=true}}}else if(myControl[0].type=="checkbox"){for(j=0;j<newArray.length;j++){for(i=0;i<myControl.length;i++){if(myControl[i].value==newArray[j]||myControl[i].value==""&&myControl[i].text==newArray[j]){myControl[i].checked=true;break}}if(i===myControl.length){myControl[i]=new Option(newArray[j],newArray[j],false,false);myControl[i].checked=true}}}}}function getControlOrAADate(formName,controlName,datePrefix,emptyValue){if(getControlByName(formName,controlName)!=null){return getControlValue(formName,controlName)}if(getControlByName(formName,datePrefix+controlName+"_day")!=null){return getAADate(formName,datePrefix+controlName,emptyValue)/1e3}return null}function getControlValue(formName,controlName){var myControl=getControlByName(formName,controlName);try{var ret=new FormData(document.querySelector('form[name="'+formName+'"]')).get(controlName)}catch(e){return null}if((ret==="on"||ret===null)&&myControl!==null&&myControl.type==="checkbox"){ret=myControl.checked?1:0}return ret}function aa_runevent(e){var func="aa_on"+e.type.charAt(0).toUpperCase()+e.type.slice(1);var fld=e.target.name.match(/aa\[[^\]]*\]\[([a-z0-9_]*)\]/);if(fld&&fld.length>0){fld=fld[1].replaceAll("_",".")}if(fld&&typeof window[func]==="function"){window[func](fld)}}function getField(fieldID){var val=getControlOrAADate("inputform","v"+unpackID(fieldID),"tdctr_","");return val!=null?val:getControlValue("inputform",document.querySelector('form[name="'+"inputform"+'"] :is(input,select,textarea)[name*="['+fieldID.replaceAll(".","_")+']"').getAttribute("name"))}function setField(fieldID,newValue){var myDate=new Date;setControlOrAADate("inputform","v"+unpackID(fieldID),newValue,"tdctr_",0,myDate.getTimezoneOffset()/60)}function hideField(fieldID){[].forEach.call(document.querySelectorAll(".cont-v"+unpackID(fieldID)),function(e){e.style.display="none"})}function showField(fieldID){[].forEach.call(document.querySelectorAll(".cont-v"+unpackID(fieldID)),function(e){e.style.display=""})}function selectAllInBox(formName,controlName){var myControl=getControlByName(formName,controlName);if(myControl!=null){for(var i=0;i<myControl.options.length;i++)myControl.options[i].selected=true}}